      out.write("\";\n");
      out.write("										// 1. 데이터를 불러오고 화면을 갱신하는 핵심 함수\n");
      out.write("										function loadCity(cityId, btn) {\n");
      out.write("											if (!btn) return;\n");
      out.write("\n");
      out.write("											sessionStorage.setItem(\"lastCityId\", cityId);\n");
      out.write("\n");
      out.write("											document.querySelectorAll('.city-btn').forEach(b => b.classList.remove('active'));\n");
      out.write("											btn.classList.add('active');\n");
      out.write("\n");
      out.write("											const contextPath = CONTEXT_PATH;\n");
      out.write("\n");
      out.write("											// 전체보기 링크 갱신\n");
      out.write("											document.querySelectorAll('.all-link').forEach(link => {\n");
      out.write("												const catCode = link.getAttribute('data-cat');\n");
      out.write("												link.href = contextPath + \"/spots/all?cityId=\" + cityId + \"&catCode=\" + catCode;\n");
      out.write("											});\n");
      out.write("\n");
      out.write("											fetch(contextPath + \"/spots/api/contents?cityId=\" + cityId)\n");
      out.write("												.then(res => res.json())\n");
      out.write("												.then(data => {\n");
      out.write("													// 데이터가 넘어오는지 콘솔에서 확인\n");
      out.write("													console.log(\"실제 데이터 구조:\", data.tourList[0]);\n");
      out.write("													console.log(\"Fetched Data:\", data);\n");
      out.write("\n");
      out.write("													renderSection('tour-slider', data.tourList, '🏛️');\n");
      out.write("													renderSection('stay-slider', data.stayList, '🛌');\n");
      out.write("													renderSection('act-slider', data.actList, '🏄');\n");
      out.write("													renderSection('food-slider', data.foodList, '🍱');\n");
      out.write("												})\n");
      out.write("												.catch(err => console.error(\"데이터 로딩 실패:\", err));\n");
      out.write("										}\n");
      out.write("\n");
      out.write("										// 2. 섹션 그리기 함수 (JSP 충돌 방지 처리가 완료된 버전)\n");
      out.write("\n");
      out.write("										// ✅ 카드 제목/주소가 길면 자동 마키(옆으로 흐름) 적용\n");
      out.write("										function initSpotMarquee(scopeEl) {\n");
      out.write("											if (!scopeEl) return;\n");
      out.write("\n");
      out.write("											const nodes = scopeEl.querySelectorAll('[data-marquee-text]');\n");
      out.write("											nodes.forEach(el => {\n");
      out.write("												if (el.dataset && el.dataset.marqueeInit === \"1\") return;\n");
      out.write("\n");
      out.write("												const txt = (el.textContent || '').trim();\n");
      out.write("												if (!txt) return;\n");
      out.write("\n");
      out.write("												// 렌더 직후 overflow 계산을 위해 한 프레임 뒤에 처리\n");
      out.write("												requestAnimationFrame(() => {\n");
      out.write("													const need = el.scrollWidth > el.clientWidth + 2;\n");
      out.write("													if (!need) {\n");
      out.write("														el.dataset.marqueeInit = \"1\";\n");
      out.write("														return;\n");
      out.write("													}\n");
      out.write("\n");
      out.write("													el.classList.add('is-marquee');\n");
      out.write("\n");
      out.write("													const track = document.createElement('span');\n");
      out.write("													track.className = 'spot-marquee-track';\n");
      out.write("\n");
      out.write("													const a = document.createElement('span');\n");
      out.write("													a.className = 'spot-marquee-item';\n");
      out.write("													a.textContent = txt;\n");
      out.write("\n");
      out.write("													const b = document.createElement('span');\n");
      out.write("													b.className = 'spot-marquee-item';\n");
      out.write("													b.textContent = txt;\n");
      out.write("\n");
      out.write("													track.appendChild(a);\n");
      out.write("													track.appendChild(b);\n");
      out.write("\n");
      out.write("													// 거리/시간 계산 (너무 빠르지 않게)\n");
      out.write("													const dist = a.getBoundingClientRect().width + 22; // gap 포함\n");
      out.write("													const speed = 50; // px/s\n");
      out.write("													const dur = Math.max(6, dist / speed);\n");
      out.write("\n");
      out.write("													track.style.setProperty('--spotMarqueeDist', dist + 'px');\n");
      out.write("													track.style.setProperty('--spotMarqueeDur', dur + 's');\n");
      out.write("\n");
      out.write("													el.innerHTML = '';\n");
      out.write("													el.appendChild(track);\n");
      out.write("\n");
      out.write("													el.dataset.marqueeInit = \"1\";\n");
      out.write("												});\n");
      out.write("											});\n");
      out.write("										}\n");
      out.write("\n");
      out.write("\n");
      out.write("										function renderSection(containerId, list, emoji) {\n");
      out.write("											const container = document.getElementById(containerId);\n");
