      out.write("\n");
      out.write("											if (!list || list.length === 0) {\n");
      out.write("												container.innerHTML = '<p style=\"padding:40px; color:#999; text-align:center; width:100%;\">등록된 정보가 없습니다. 😊</p>';\n");
      out.write("												return;\n");
      out.write("											}\n");
      out.write("\n");
      out.write("											// 이미지 URL 정규화(상대/절대/외부링크 모두 대응)\n");
      out.write("											const resolveImg = (raw) => {\n");
      out.write("												if (!raw) return CONTEXT_PATH + '/img/hero.jpg'; // 기본 이미지\n");
      out.write("												const s = String(raw).trim();\n");
      out.write("												if (!s) return CONTEXT_PATH + '/img/hero.jpg';\n");
      out.write("												if (s.startsWith('http://') || s.startsWith('https://') || s.startsWith('data:')) return s;\n");
      out.write("												if (s.startsWith(CONTEXT_PATH + '/')) return s;\n");
      out.write("												if (s.startsWith('/')) return CONTEXT_PATH + s;\n");
      out.write("												return CONTEXT_PATH + '/' + s.replace(/^\\/+/, '');\n");
      out.write("											};\n");
      out.write("\n");
      out.write("											// renderSection 함수 내부의 list.forEach 부분을 찾아서 아래와 같이 수정하세요.\n");
      out.write("											list.forEach(s => {\n");
      out.write("												const spotId = s.id || s.s_idx || s.sIdx;\n");
      out.write("												const spotName = s.name || s.s_name || s.sname || '이름 없음';\n");
      out.write("												const spotAddr = s.addr || s.s_addr || s.saddr || '주소 정보 없음';\n");
      out.write("												const isHearted = s.isHearted || false; // 서버에서 넘어온 찜 상태\n");
      out.write("\n");
      out.write("												const rawImg = s.img || s.sImg || s.s_img || s.image || s.imageUrl;\n");
      out.write("												const spotImg = resolveImg(rawImg);\n");
      out.write("\n");
      out.write("												const cardHtml = `\n");
      out.write("					        <div class=\"card-item\" style=\"position: relative;\">\n");
      out.write("					            <button class=\"wish-btn ${isHearted ? 'active' : ''}\" \n");
      out.write("					                    type=\"button\" \n");
      out.write("					                    onclick=\"toggleWish(event, ${spotId}, this)\" \n");
      out.write("					                    style=\"position: absolute; top: 12px; right: 12px; z-index: 10;\">\n");
      out.write("					                ${isHearted ? '❤️' : '🤍'}\n");
      out.write("					            </button>\n");
      out.write("\n");
      out.write("					            <a class=\"spot-link\" href=\"");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${pageContext.request.contextPath}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("/spots/detail/${spotId}\">\n");
      out.write("					                <div class=\"spot-card\">\n");
      out.write("					                    <div class=\"spot-thumb\">\n");
      out.write("					                        <img class=\"spot-img\" src=\"${spotImg}\" alt=\"${spotName}\"\n");
      out.write("					                             onerror=\"this.onerror=null; this.src='");
      out.write((java.lang.String) org.apache.jasper.runtime.PageContextImpl.proprietaryEvaluate("${pageContext.request.contextPath}", java.lang.String.class, (jakarta.servlet.jsp.PageContext)_jspx_page_context, null));
      out.write("/img/hero.jpg';\" />\n");
      out.write("					                        <div class=\"spot-overlay\"></div>\n");
      out.write("					                        <div class=\"spot-text\">\n");
      out.write("					                            <div class=\"spot-title\" data-marquee-text>${spotName}</div>\n");
      out.write("					                            <div class=\"spot-addr\" data-marquee-text>${spotAddr}</div>\n");
      out.write("					                        </div>\n");
      out.write("					                    </div>\n");
      out.write("					                </div>\n");
      out.write("					            </a>\n");
      out.write("					        </div>\n");
      out.write("					    `;\n");
      out.write("												container.insertAdjacentHTML('beforeend', cardHtml);\n");
      out.write("											});\n");
      out.write("\n");
      out.write("											initSpotMarquee(container);\n");
      out.write("										}\n");
      out.write("\n");
      out.write("										// 3. 슬라이더 이동 함수\n");
      out.write("										function sideScroll(elementId, direction) {\n");
      out.write("											const container = document.getElementById(elementId);\n");
      out.write("											const card = container.querySelector('.card-item');\n");
      out.write("											if (!card) return;\n");
      out.write("											const scrollAmount = card.clientWidth + 20;\n");
      out.write("											if (direction === 'left') container.scrollLeft -= scrollAmount;\n");
      out.write("											else container.scrollLeft += scrollAmount;\n");
      out.write("										}\n");
      out.write("\n");
      out.write("										// 4. 페이지 진입 시 실행 로직\n");
      out.write("										document.addEventListener(\"DOMContentLoaded\", function () {\n");
      out.write("											const savedCityId = sessionStorage.getItem(\"lastCityId\") || \"4\";\n");
      out.write("											const buttons = document.querySelectorAll('.city-btn');\n");
      out.write("											let targetBtn = null;\n");
      out.write("\n");
      out.write("											buttons.forEach(btn => {\n");
      out.write("												if (btn.getAttribute('onclick').includes(savedCityId)) {\n");
      out.write("													targetBtn = btn;\n");
      out.write("												}\n");
      out.write("											});\n");
      out.write("\n");
      out.write("											if (targetBtn) {\n");
      out.write("												loadCity(savedCityId, targetBtn);\n");
      out.write("											} else if (buttons.length > 0) {\n");
      out.write("												loadCity(\"4\", buttons[0]);\n");
      out.write("											}\n");
      out.write("\n");
      out.write("\n");
      out.write("										});\n");
      out.write("\n");
      out.write("										function toggleWish(event, sIdx, btn) {\n");
      out.write("											// 1. 상세 페이지 이동 방지\n");
      out.write("											event.preventDefault();\n");
      out.write("											event.stopPropagation();\n");
      out.write("\n");
      out.write("											// 2. 서버 통신\n");
      out.write("											fetch('/api/wish/toggle', {\n");
      out.write("												method: 'POST',\n");
      out.write("												headers: {\n");
      out.write("													'Content-Type': 'application/json'\n");
      out.write("												},\n");
      out.write("												body: JSON.stringify({sIdx: sIdx})\n");
      out.write("											})\n");
      out.write("												.then(response => {\n");
      out.write("													if (response.status === 401) {\n");
      out.write("														if (window.LoginRequiredPrompt) { window.LoginRequiredPrompt.open(); } else { if (window.LoginRequiredPrompt) { window.LoginRequiredPrompt.open(); } else { alert('로그인이 필요한 서비스입니다.'); } }\n");
      out.write("														return;\n");
      out.write("													}\n");
      out.write("													return response.json();\n");
      out.write("												})\n");
      out.write("												.then(data => {\n");
      out.write("													if (data && data.success) {\n");
      out.write("														btn.innerText = data.isHearted ? '❤️' : '🤍';\n");
      out.write("\n");
      out.write("														// CSS의 .active 스타일을 적용/해제함\n");
      out.write("														if (data.isHearted) {\n");
      out.write("															btn.classList.add('active');\n");
      out.write("														} else {\n");
      out.write("															btn.classList.remove('active');\n");
      out.write("														}\n");
      out.write("													}\n");
      out.write("												})\n");
      out.write("												.catch(error => {\n");
      out.write("													console.error('Error:', error);\n");
      out.write("													alert('처리 중 오류가 발생했습니다.');\n");
      out.write("												});\n");
      out.write("										}\n");
      out.write("\n");
      out.write("									</script>\n");
      out.write("\n");
      out.write("									</div>\n");
      out.write("\n");
      out.write("\n");
